static std::vector<std::string> files(){std::vector<std::string> names;DIR* d=opendir("projects");if(d){while(auto* f=readdir(d)){std::string n=f->d_name;if(n.size()>5&&n.substr(n.size()-5)==".json")names.push_back(n);}closedir(d);}std::sort(names.begin(),names.end());return names;}
static std::vector<std::string> wavFiles(){std::vector<std::string> names;DIR* directory=opendir("samples");if(directory){while(auto* entry=readdir(directory)){std::string name=entry->d_name,lower=name;std::transform(lower.begin(),lower.end(),lower.begin(),[](unsigned char c){return std::tolower(c);});if(lower.size()>4&&lower.substr(lower.size()-4)==".wav")names.push_back(name);}closedir(directory);}std::sort(names.begin(),names.end());return names;}
static bool exportWave(Json p,const std::string& file){
    p["songLoop"]=false;AudioEngine engine(p);preloadSamples(engine);engine.start();std::ofstream out(file,std::ios::binary);if(!out)return false;out.write("RIFF",4);uint32_t size=0;out.write(reinterpret_cast<char*>(&size),4);out.write("WAVEfmt ",8);uint32_t fmtSize=16;uint16_t format=1,channels=2,bits=16,align=4;uint32_t sampleRate=SR,rate=SR*4;out.write(reinterpret_cast<char*>(&fmtSize),4);out.write(reinterpret_cast<char*>(&format),2);out.write(reinterpret_cast<char*>(&channels),2);out.write(reinterpret_cast<char*>(&sampleRate),4);out.write(reinterpret_cast<char*>(&rate),4);out.write(reinterpret_cast<char*>(&align),2);out.write(reinterpret_cast<char*>(&bits),2);out.write("data",4);out.write(reinterpret_cast<char*>(&size),4);
    int bars=1;if(str(p,"playMode")=="song"){bars=0;for(const auto& r:p["song"])bars+=static_cast<int>(get(r,"repeats",1));}const double duration=bars*32*60/get(p,"bpm",96)/4;auto tail=[](const Json& f){double seconds=3;const auto& delay=f["delay"];if(flag(delay,"enabled")&&get(delay,"mix")>0){const double feedback=get(delay,"feedback");seconds+=get(delay,"time")*(feedback>0?std::ceil(std::log(.001)/std::log(feedback)):1);}const auto& reverb=f["reverb"];if(flag(reverb,"enabled")&&get(reverb,"mix")>0)seconds+=get(reverb,"decay");return seconds;};double extra=0;for(const auto& fx:p["trackFx"])extra=std::max(extra,tail(fx)-3);const int64_t total=static_cast<int64_t>((duration+tail(p["fx"])+extra)*SR);std::array<int16_t,1024> block{};
    for(int64_t n=0;n<total;n+=512){if(n>=duration*SR)engine.playing=false;const int count=static_cast<int>(std::min<int64_t>(512,total-n));engine.render(block.data(),count);out.write(reinterpret_cast<const char*>(block.data()),count*4);size+=count*4;}out.seekp(40);out.write(reinterpret_cast<char*>(&size),4);uint32_t riff=size+36;out.seekp(4);out.write(reinterpret_cast<char*>(&riff),4);return out.good();
}

